    kn: "ಸಕ್ರಿಯ ತೆನೆ ಪ್ರಾರಂಭವನ್ನು ದೃಢೀಕರಿಸಲಾಗಿದೆ. ಹಸಿರು ಎಲೆಗಳು ಮತ್ತು ಬಲವಾದ ಬೇರಿನ ಹೀರಿಕೊಳ್ಳುವಿಕೆಯೊಂದಿಗೆ ಬೆಳೆ ಬೆಳವಣಿಗೆ ಸಾಗುತ್ತಿದೆ.",
