// Smart string translator
export function translateText(text: string, lang: LanguageCode = 'en'): string {
  if (!text || lang === 'en') return text;
  
  // Exact dictionary match
  if (DYNAMIC_DICTIONARY[text]?.[lang]) {
    return DYNAMIC_DICTIONARY[text][lang];
  }

  // Trimmed match
  const trimmed = text.trim();
  if (DYNAMIC_DICTIONARY[trimmed]?.[lang]) {
    return DYNAMIC_DICTIONARY[trimmed][lang];
  }

  // Dynamic parameterized string replacement for notifications & messages
  if (trimmed.includes('Paddy is currently Day') && trimmed.includes('Common weed expected')) {
    if (lang === 'te') return 'వరి ప్రస్తుతం 42వ రోజులో ఉంది. ఆశించే కలుపు: ఊద గడ్డి. చర్య: పొలాన్ని పరిశీలించి విత్తనాలు రాకముందే కలుపు తీయండి.';
    if (lang === 'hi') return 'धान वर्तमान में दिन 42 पर है। संभावित खरपतवार: सांवा घास। कार्रवाई: खेत का निरीक्षण करें और बीज बनने से पहले निकालें।';
    if (lang === 'ta') return 'நெல் தற்போது நாள் 42 இல் உள்ளது. எதிர்பார்க்கப்படும் களை: காடைக்கண்ணி புல். நடவடிக்கை: நிலத்தை ஆய்வு செய்து களையெடுக்கவும்.';
    if (lang === 'kn') return 'ಭತ್ತ ಪ್ರಸ್ತುತ 42ನೇ ದಿನದಲ್ಲಿದೆ. ನಿರೀಕ್ಷಿತ ಕಳೆ: ಕಾಡು ಹುಲ್ಲು. ಕ್ರಮ: ಜಮೀನನ್ನು ಪರಿಶೀಲಿಸಿ ಕಳೆ ತೆಗೆಯಿರಿ.';
  }

  if (trimmed.startsWith('Today,')) {
    const timePart = trimmed.replace('Today,', '').trim();
    if (lang === 'te') return `ఈరోజు, ${timePart}`;
    if (lang === 'hi') return `आज, ${timePart}`;
    if (lang === 'ta') return `இன்று, ${timePart}`;
    if (lang === 'kn') return `ಇಂದು, ${timePart}`;
  }

  // Weather Recommendation: Rain Expected Soon
  if (trimmed.startsWith('Rainfall (') && trimmed.includes('is forecast.')) {
    const match = trimmed.match(/Rainfall \((\d+)% chance tomorrow, (\d+)% ([^)]+)\) is forecast\.(.*)/);
    if (match) {
      const [, p1, p2, dayName] = match;
      const translatedDay = translateText(dayName, lang);
      if (lang === 'te') return `వర్షపాతం రేపు (${p1}% అవకాశం), ${translatedDay} (${p2}% అవకాశం) కురిసే సూచన ఉంది. అత్యంత పొడి విభాగాలు తప్ప నేడు నీటిపారుదల అవసరం లేదు.`;
      if (lang === 'hi') return `कल (${p1}% संभावना) और ${translatedDay} (${p2}% संभावना) बारिश का पूर्वानुमान है। बहुत सूखे क्षेत्रों को छोड़कर आज सिंचाई की आवश्यकता नहीं हो सकती है।`;
      if (lang === 'ta') return `நாளை (${p1}% வாய்ப்பு), ${translatedDay} (${p2}% வாய்ப்பு) மழை பெய்ய வாய்ப்புள்ளது. மிகவும் வறண்ட பகுதிகளைத் தவிர இன்று நீர்ப்பாசனம் தேவையில்லை.`;
      if (lang === 'kn') return `ನಾಳೆ (${p1}% సంభవనీయతే), ${translatedDay} (${p2}% సంభవనీయతే) ಮಳೆಯ ಮುನ್ಸೂಚನೆ ಇದೆ. ಅತ್ಯಂತ ಒಣ ಪ್ರದೇಶಗಳನ್ನು ಹೊರತುಪಡಿಸಿ ಇಂದು ನೀರಾವರಿ ಅಗತ್ಯವಿಲ್ಲದಿರಬಹುದು.`;
    }
  }

  // Weather Recommendation: High Humidity Disease Risk
  if (trimmed.startsWith('High humidity (')) {
    const match = trimmed.match(/High humidity \((\d+)%\) and cooler night temperatures increase the risk of fungal infections such as (.*)\./);
    if (match) {
      const [, hum, diseases] = match;
      const translatedDiseases = translateText(diseases, lang);
      if (lang === 'te') return `అధిక గాలి తేమ (${hum}%) మరియు రాత్రి చల్లని ఉష్ణోగ్రతలు ${translatedDiseases} వంటి శిలీంధ్ర తెగుళ్ళ ప్రమాదాన్ని పెంచుతాయి.`;
      if (lang === 'hi') return `उच्च आर्द्रता (${hum}%) और ठंडी रात का तापमान ${translatedDiseases} जैसे फंगल संक्रमण के जोखिम को बढ़ाता है।`;
      if (lang === 'ta') return `அதிக ஈரப்பதம் (${hum}%) மற்றும் குளிர்ந்த இரவு வெப்பநிலை ${translatedDiseases} போன்ற பூஞ்சை தொற்றுகளின் அபாயத்தை உயர்த்துகிறது.`;
      if (lang === 'kn') return `ಹೆಚ್ಚಿನ ತೇವಾಂಶ (${hum}%) ಮತ್ತು ತಂಪಾದ ರಾತ್ರಿ ತಾಪಮಾನವು ${translatedDiseases} ನಂತಹ ಶಿಲೀಂಧ್ರ ಸೋಂಕಿನ ಅಪಾಯವನ್ನು ಹೆಚ್ಚಿಸುತ್ತದೆ.`;
    }
  }

  // Weather Recommendation: Heat Stress Alert
  if (trimmed.startsWith('Daytime temperatures reaching')) {
    const match = trimmed.match(/Daytime temperatures reaching (\d+)°C\. Ensure adequate moisture is maintained in the root zone during (.*)\./);
    if (match) {
      const [, temp, stage] = match;
      const translatedStage = translateText(stage, lang);
      if (lang === 'te') return `పగటి ఉష్ణోగ్రతలు ${temp}°C కి చేరుకుంటున్నాయి. ${translatedStage} లో వేరు మండలంలో తగినంత తేమ ఉండేలా చూసుకోండి.`;
      if (lang === 'hi') return `दिन का तापमान ${temp}°C तक पहुंच रहा है। ${translatedStage} के दौरान जड़ क्षेत्र में पर्याप्त नमी बनाए रखें।`;
      if (lang === 'ta') return `பகல் வெப்பநிலை ${temp}°C ஐ எட்டுகிறது. ${translatedStage} இன் போது வேர் மண்டலத்தில் போதிய ஈரப்பதத்தை பராமரிக்கவும்.`;
      if (lang === 'kn') return `ಹಗಲಿನ ತಾಪಮಾನವು ${temp}°C ತಲುಪುತ್ತಿದೆ. ${translatedStage} ಅವಧಿಯಲ್ಲಿ ಬೇರಿನ ವಲಯದಲ್ಲಿ ಸೂಕ್ತ ತೇವಾಂಶವನ್ನು ಕಾಯ್ದುಕೊಳ್ಳಿ.`;
    }
  }

  // Weather Recommendation: Heavy Rain Drainage Check
  if (trimmed.startsWith('Heavy showers (')) {
    const match = trimmed.match(/Heavy showers \((\d+(?:\.\d+)?)mm\) expected on ([^\.]+)\. Check bund outlets and field drainage channels to prevent waterlogging\./);
    if (match) {
      const [, mm, dayName] = match;
      const translatedDay = translateText(dayName, lang);
      if (lang === 'te') return `${translatedDay} న భారీ వర్షం (${mm}మిమీ) కురిసే అవకాశం ఉంది. నీరు నిలవకుండా పొలం గట్ల ద్వారాలు మరియు కాలువలను శుభ్రం చేయండి.`;
      if (lang === 'hi') return `${translatedDay} को भारी बारिश (${mm}mm) की उम्मीद है। जलभराव को रोकने के लिए मेढ़ के निकास और जल निकासी नालियों की जांच करें।`;
      if (lang === 'ta') return `${translatedDay} அன்று கனமழை (${mm}மிமீ) எதிர்பார்க்கப்படுகிறது. நீர் தேங்குவதைத் தடுக்க வரப்பு வடிகால்களைச் சரிபார்க்கவும்.`;
      if (lang === 'kn') return `${translatedDay} ರಂದು ಭಾರಿ ಮಳೆ (${mm}mm) ನಿರೀಕ್ಷಿಸಲಾಗಿದೆ. ನೀರು ನಿಲ್ಲದಂತೆ ಜಮೀನಿನ ನೀರು ಹರಿಯುವ ಕಾಲುವೆಗಳನ್ನು ಪರಿಶೀಲಿಸಿ.`;
    }
  }

  // Actionable tip: Clear silt...
  if (trimmed.startsWith('Clear silt and weed blockages')) {
    const match = trimmed.match(/Clear silt and weed blockages from field drainage trenches before (.*)\./);
    if (match) {
      const [, dayName] = match;
      const translatedDay = translateText(dayName, lang);
      if (lang === 'te') return `${translatedDay} కల్లా పొలం నీటి పారుదల కాలువలలోని పూడిక మరియు కలుపు అడ్డంకులను తొలగించండి.`;
      if (lang === 'hi') return `${translatedDay} से पहले खेत की जल निकासी नालियों से गाद और खरपतवार की रुकावटें हटाएं।`;
      if (lang === 'ta') return `${translatedDay} ஆம் தேதிக்கு முன் நில வடிகால் வாய்க்கால்களில் உள்ள வண்டல் மற்றும் களை அடைப்புகளை அகற்றவும்.`;
      if (lang === 'kn') return `${translatedDay} ಕ್ಕಿಂತ ಮೊದಲು ಜಮೀನಿನ ನೀರು ಹರಿಯುವ ಕಾಲುವೆಗಳಿಂದ ಹೂಳು ಮತ್ತು ಕಳೆ ತಡೆಗಳನ್ನು ತೆರவுಗೊಳಿಸಿ.`;
    }
  }

  // Compound splitting: "Field 01 - Paddy Main Plot" -> "Field 01" - "Paddy Main Plot"
  if (text.includes(' - ')) {
    const parts = text.split(' - ');
    const translatedParts = parts.map(p => translateText(p, lang));
    return translatedParts.join(' - ');
  }

  // Compound splitting: "Paddy Blast and Brown Spot" -> "Paddy Blast" and "Brown Spot"
  if (text.includes(' and ')) {
    const parts = text.split(' and ');
    const translatedParts = parts.map(p => translateText(p, lang));
    const andWord: Record<LanguageCode, string> = {
      en: ' and ',
      te: ' మరియు ',
      hi: ' और ',
      ta: ' மற்றும் ',
      kn: ' ಮತ್ತು ',
    };
    return translatedParts.join(andWord[lang] || ' and ');
  }

  return text;
}
